head.script:
        	scwin.onpageload = function() {
        		var jsonData = [{"col1":"1","col2":"1","col3":"1"},{"col1":"1","col2":"1","col3":"2"}
        						,{"col1":"1","col2":"1","col3":"3"},{"col1":"1","col2":"1","col3":"4"}
        						,{"col1":"1","col2":"1","col3":"5"},{"col1":"1","col2":"1","col3":"6"}];
        		dataList1.setJSON(jsonData);
        	}


			scwin.trigger1_onclick = function(e) {
                var infoArr = []; 
                var infoObj = { 
                    rowIndex:   1, 
                    colIndex:   3, 
                    rowSpan:    1, 
                    colSpan:    1, 
                    text:       "3", 
                    textAlign:  "center" 
                }; 
                infoArr.push( infoObj ); 

                var infoObj = { 
                    rowIndex:   1, 
                    colIndex:   4, 
                    rowSpan:    1, 
                    colSpan:    1, 
                    text:       "4", 
                    textAlign:  "center" 
                }; 
                infoArr.push( infoObj ); 

                //=D2*$E$2

                var infoObj = { 
                    rowIndex:   1, 
                    colIndex:   5, 
                    rowSpan:    1, 
                    colSpan:    1, 
                    text:       "",
                    excelExpression : "D2*$E$2",
                    textAlign:  "center" 
                }; 
                infoArr.push( infoObj ); 

		    	var options = { 
				    type:               "1", 
				    fileName : "excelExpressionTest.xlsx",
                    startRowIndex : "7",
				    useDataFormat : "true"
				}; 
				gridView1.advancedExcelDownload(options, infoArr);
			};

			scwin.gridView1_onfilereadend = function(value) {

			};

scwin.btn_add_onclick = function(e) {
    var row = dataList1.getTotalRow();
	dataList1.insertRow(row);


	gridView1.setFocusedCell(row, "col1");
  dataList1.setCellData(row, "col1", row);
};

scwin.btn_remove_onclick = function(e) {
  debugger;
  var row       = dataList1.getRowPosition();
  var strStatus = dataList1.getRowStatus(row);

  if(strStatus == "C")
  {
    dataList1.removeRow(row);
  }
  else
  {
    dataList1.deleteRow(row);

  }
};

	scwin.getVisibleRowCount = function() {

		const rows = WebSquare.wUnit.getDomById('gridView1_body_tbody').querySelectorAll('tr');

		let visibleRowCount = 0;

		rows.forEach(row => {
			if (!row.classList.contains('w2grid_hidedRow')) {
				visibleRowCount++; 
			}
		});
		console.log(visibleRowCount);
		return visibleRowCount; // 가시적인 tr의 갯수 반환
	}
	scwin.checkVal1 = function() {
		return scwin.getVisibleRowCount() == 11;
	}				
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView1_headerRowStatus_bodyRow_9').classList.contains('w2grid_rowStatus_C');
	}				
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_add').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_add').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_add').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_add').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_add').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_6_0').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_remove').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
